// What comes back from Telegram. Three kinds of thing arrive and only two of
// them do anything in this slice: a tapped button, and /start with a pairing
// code. Free text is read by nothing yet.
//
// A CHAT ID IS UNTRUSTED INPUT. It becomes an account in exactly one way, a
// code that was generated by the app and redeemed inside the store (see
// ./pairing), and an unknown chat is ignored without a reply, so this endpoint
// cannot be used to find out whether a chat is linked.
//
// Everything here is idempotent, because Telegram retries webhooks and people
// double-tap: `asks.answer` is one conditional update, and a tap that changes
// nothing only re-acknowledges what was already recorded.

import { z } from "zod";

import { answeredText } from "@/app/lib/v2/channel/messages";
import {
  OPTION_ID_MAX,
  applyEffect,
  createEngineContext,
  planToday,
  wholeSecond,
  type TickDeps,
} from "@/app/lib/v2/engine/tick";
import { redeemPairingCode } from "@/app/lib/v2/engine/pairing";
import type { Ask, Incoming, Instant } from "@/app/lib/v2/types";

export const LINKED_TEXT = "Linked. I will message you here.";
export const CODE_REFUSED_TEXT = "That code is not valid any more. Make a new one in Mindboard.";

/**
 * What the caller knows about the message a button was tapped on. Telegram puts
 * both in the callback update (see `callbackMessage`), and they are the only
 * source: the stores can answer "which ask is this?" but not "which message
 * carried it", so a caller that has neither still gets the acknowledgement and
 * the ask's own text.
 */
export interface IncomingContext {
  chatMessageId?: string | null;
  chatMessageText?: string | null;
}

const callbackSchema = z.object({
  callback_query: z.object({
    message: z
      .object({
        message_id: z.union([z.number(), z.string().min(1)]).optional(),
        text: z.string().optional(),
      })
      .optional(),
  }),
});

/**
 * The id and current text of the message a callback came from. Data, not
 * instructions: both values are echoed back to the same chat and nowhere else.
 */
export function callbackMessage(update: unknown): {
  messageId: string | null;
  text: string | null;
} {
  const parsed = callbackSchema.safeParse(update);
  if (!parsed.success) return { messageId: null, text: null };
  const message = parsed.data.callback_query.message;
  return {
    messageId: message?.message_id === undefined ? null : String(message.message_id),
    text: message?.text ?? null,
  };
}

/** The acknowledgement for a tap that changed nothing. */
function alreadyAnswered(ask: Ask): string {
  // An ask that is still open was not answered by this tap at all (an option it
  // never had), so there is nothing to report: the empty text just dismisses
  // the button's spinner.
  return ask.status === "open" ? "" : answeredText(ask);
}

async function handleAnswer(
  deps: TickDeps,
  incoming: Extract<Incoming, { type: "answer" }>,
  now: Instant,
  context: IncomingContext,
): Promise<void> {
  const userId = await deps.stores.channels.userForChat(incoming.chatId);
  if (userId === null) return;

  // The store refuses an option id past the contract's 12 characters with a
  // row-shape error, which a forged callback must not be able to raise.
  const answered =
    incoming.optionId.length > 0 && incoming.optionId.length <= OPTION_ID_MAX
      ? await deps.stores.asks.answer(userId, incoming.askId, incoming.optionId, now)
      : null;

  if (answered === null) {
    const existing = await deps.stores.asks.get(userId, incoming.askId);
    if (existing === null) return; // not this account's ask, or not an ask at all
    await deps.telegram?.answerCallback(incoming.callbackId, alreadyAnswered(existing));
    return;
  }

  const option = answered.options.find((candidate) => candidate.id === incoming.optionId);
  const ctx = await createEngineContext(deps, userId, now);
  await applyEffect(ctx, option?.effect ?? { type: "none" });
  try {
    await planToday(ctx);
  } catch (error) {
    // The answer is already recorded and its effect applied, so a replan that
    // cannot run must not swallow the acknowledgement: the next tick plans
    // again within ten minutes. One line, the class only.
    const kind = error instanceof Error ? error.name : typeof error;
    console.warn(`v2 answer: the replan failed for ${userId} (${kind})`);
  }

  if (deps.telegram === null) return;
  const text = answeredText(answered);
  await deps.telegram.answerCallback(incoming.callbackId, text);
  const messageId = context.chatMessageId ?? null;
  if (messageId === null) return;
  const original = context.chatMessageText ?? answered.text;
  await deps.telegram.replaceButtons(incoming.chatId, messageId, `${original}\n${text}`);
}

async function handleStart(
  deps: TickDeps,
  incoming: Extract<Incoming, { type: "start" }>,
  now: Instant,
): Promise<void> {
  const userId =
    incoming.pairingCode === null
      ? null
      : await redeemPairingCode(deps.stores, incoming.pairingCode, incoming.chatId, now);
  await deps.telegram?.sendMessage(incoming.chatId, {
    text: userId === null ? CODE_REFUSED_TEXT : LINKED_TEXT,
    buttons: [],
  });
}

/**
 * Handles one update. It never throws for an update it does not understand: the
 * webhook answers 200 whatever happens, so an unparseable or foreign update has
 * to be a no-op rather than an error Telegram would retry forever.
 */
export async function handleIncoming(
  deps: TickDeps,
  incoming: Incoming,
  at: Instant,
  context: IncomingContext = {},
): Promise<void> {
  // The webhook builds `at` with `new Date().toISOString()`, so it carries
  // milliseconds. Floored here rather than only in `createEngineContext`,
  // because `asks.answer` and `redeemPairingCode` are handed it before any
  // context exists, and nothing below this line should see a fraction of a
  // second (see `wholeSecond`).
  const now = wholeSecond(at);
  switch (incoming.type) {
    case "answer":
      await handleAnswer(deps, incoming, now, context);
      return;
    case "start":
      await handleStart(deps, incoming, now);
      return;
    case "text":
      // Nothing reads free text in this slice. Deliberately silent: a reply
      // would invite a conversation the engine cannot have yet.
      return;
  }
}
